/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/phase16-live-litres-pin.json: the litres of
 * the 74 Phase 16 test boards (`phase16LiveBoards`, lib/geometry/__fixtures__/phase16-boards.ts) as go-live 1
 * works them out — the tail's Hard Edge fading between Blends From and Ends At, every other rail box still
 * switching halfway between two anchors — BEFORE the whole rail character fades (D-32, plan 16-15). The
 * output is generated and must never be hand-edited.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-phase16-live-litres-pin.ts
 *
 * run from the repository root. Like the first Phase 16 pin, it is a record of the code as it stood, so it
 * REFUSES to run once `lib/geometry/volume.ts` exports `RAIL_CHARACTER_FADE`: from then on the figures it
 * would write are the new rule's own, and the pin would prove nothing. It ran exactly once. (Nothing in
 * package.json — `--no-install` means npx can only run the tsx already in node_modules. No database is
 * involved.)
 *
 * Each figure is `summarizeDesign(fields).volumeLitres.toPrecision(17)`, a string, so the test compares
 * every digit a double holds.
 */
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import { phase16LiveBoards } from "@/lib/geometry/__fixtures__/phase16-boards";
import { summarizeDesign } from "@/lib/geometry/design";
import * as volume from "@/lib/geometry/volume";

const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/phase16-live-litres-pin.json");

function main() {
  if (!existsSync(path.resolve(process.cwd(), "lib/geometry/volume.ts"))) {
    throw new Error("Run this from the repository root (lib/geometry/volume.ts not found here).");
  }
  if ("RAIL_CHARACTER_FADE" in volume) {
    throw new Error("the pin records go-live 1's litres from before the rail character faded — it is never re-run");
  }
  const litres: Record<string, string> = {};
  for (const board of phase16LiveBoards()) {
    litres[board.label] = summarizeDesign(board.fields).volumeLitres.toPrecision(17);
  }
  const provenance =
    "GENERATED by scripts/extract-phase16-live-litres-pin.ts from the app as go-live 1 shipped it, before the " +
    "whole rail character faded (phase16LiveBoards, summarizeDesign, toPrecision(17)) — never hand-edit, never re-run";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, litres }, null, 2)}\n`);
  for (const [label, value] of Object.entries(litres)) console.log(`${label}: ${Number(value).toFixed(4)} L`);
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(litres).length} boards)`);
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
